result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/forth.py", "content": """"A small Forth-like interpreter.

Usage:
    python forth.py          # start a REPL
    python -c "import forth; print(forth.run('1 2 + .'))"

Supported words:
    - Integer literals: 42, -7 ...
    - Arithmetic: + - * / mod
    - Stack manipulation: dup drop swap over rot
    - Comparison: = < >   (true is -1, false is 0)
    - Output: . (pop & print with trailing space), cr (newline),
      emit (pop & print as ASCII character)
    - Definitions: : name body ;   (usable immediately afterwards)
    - Control flow inside definitions: if / else / then (0 is false)
      and begin / until (loop while the tested value is 0/false)

Errors:
    Stack underflow and unknown words raise ForthError naming the word.
"""

from __future__ import annotations

import sys
from typing import Callable, List, Optional


class ForthError(Exception):
    """Raised for unknown words, stack underflow, and syntax problems."""


# ---------------------------------------------------------------------------
# Compiled instruction tuples:
#   ("push", n)        push integer literal
#   ("call", name)     execute word (builtin or user definition)
#   ("jz", target)     pop value; jump to target if it is 0 (false)
#   ("jmp", target)    unconditional jump
# ---------------------------------------------------------------------------

Instruction = tuple


class Forth:
    def __init__(self) -> None:
        self.stack: List[int] = []
        self.words: dict[str, Instruction] = {}
        self._install_builtins()

    # -- stack helpers ----------------------------------------------------

    def _pop(self, word: str) -> int:
        if not self.stack:
            raise ForthError(f"stack underflow: '{word}'")
        return self.stack.pop()

    def _need(self, n: int, word: str) -> None:
        if len(self.stack) < n:
            raise ForthError(f"stack underflow: '{word}'")

    # -- builtins ----------------------------------------------------------

    def _install_builtins(self) -> None:
        def binop(name: str, fn: Callable[[int, int], int]) -> None:
            def impl() -> None:
                self._need(2, name)
                b = self.stack.pop()
                a = self.stack.pop()
                self.stack.append(fn(a, b))

            self.words[name] = (("builtin", impl),)

        def trunc_div(a: int, b: int) -> int:
            if b == 0:
                raise ForthError("division by zero: '/'")
            q = a // b
            if q < 0 and q * b != a:
                q += 1  # truncate toward zero like classic Forth
            return q

        binop("+", lambda a, b: a + b)
        binop("-", lambda a, b: a - b)
        binop("*", lambda a, b: a * b)
        binop("/", trunc_div)
        binop("mod", lambda a, b: a - b * trunc_div(a, b))
        binop("=", lambda a, b: -1 if a == b else 0)
        binop("<", lambda a, b: -1 if a < b else 0)
        binop(">", lambda a, b: -1 if a > b else 0)

        def word_dup() -> None:
            self._need(1, "dup")
            self.stack.append(self.stack[-1])

        def word_drop() -> None:
            self._pop("drop")

        def word_swap() -> None:
            self._need(2, "swap")
            self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]

        def word_over() -> None:
            self._need(2, "over")
            self.stack.append(self.stack[-2])

        def word_rot() -> None:
            self._need(3, "rot")
            self.stack.append(self.stack.pop(-3))

        def word_dot() -> None:
            print(self._pop("."), end=" ")

        def word_cr() -> None:
            print()

        def word_emit() -> None:
            print(chr(self._pop("emit")), end="")

        for name, fn in [
            ("dup", word_dup),
            ("drop", word_drop),
            ("swap", word_swap),
            ("over", word_over),
            ("rot", word_rot),
            (".", word_dot),
            ("cr", word_cr),
            ("emit", word_emit),
        ]:
            self.words[name] = (("builtin", fn),)

    # -- compilation -------------------------------------------------------

    def _compile_body(self, tokens: List[str]) -> List[Instruction]:
        """Compile a definition body, resolving if/else/then and begin/until."""
        code: List[Instruction] = []
        # control-flow bookkeeping:
        #   ("if", index-of-jz) ("else", index-of-jz, index-of-jmp) ("begin", addr)
        ctrl: list[tuple] = []
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            i += 1
            if tok == "if":
                code.append(("jz", None))  # patched by else/then
                ctrl.append(("if", len(code) - 1))
            elif tok == "else":
                if not ctrl or ctrl[-1][0] != "if":
                    raise ForthError("'else' without matching 'if'")
                _, jz = ctrl.pop()
                code.append(("jmp", None))  # patched by then
                code[jz] = ("jz", len(code))  # false branch starts here
                ctrl.append(("else", len(code) - 1, jz))
            elif tok == "then":
                if not ctrl or ctrl[-1][0] not in ("if", "else"):
                    raise ForthError("'then' without matching 'if'")
                entry = ctrl.pop()
                here = len(code)
                if entry[0] == "else":
                    code[entry[1]] = ("jmp", here)
                    code[entry[2]] = ("jz", here)
                else:
                    code[entry[1]] = ("jz", here)
            elif tok == "begin":
                ctrl.append(("begin", len(code)))
            elif tok == "until":
                if not ctrl or ctrl[-1][0] != "begin":
                    raise ForthError("'until' without matching 'begin'")
                _, addr = ctrl.pop()
                code.append(("jz", addr))  # loop again when value is false
            else:
                code.extend(self._compile_token(tok))
        if ctrl:
            raise ForthError(f"unclosed '{ctrl[-1][0]}' in definition")
        return code

    def _compile_token(self, tok: str) -> List[Instruction]:
        try:
            return [("push", int(tok))]
        except ValueError:
            pass
        if tok in ("if", "else", "then", "begin", "until"):
            raise ForthError(f"'{tok}' is only allowed inside a definition")
        if tok not in self.words:
            raise ForthError(f"unknown word: '{tok}'")
        return [("call", tok)]

    def define(self, tokens: List[str]) -> None:
        """Handle ': name body ;'. `tokens` includes the leading ':'."""
        if len(tokens) < 2:
            raise ForthError("incomplete definition")
        name = tokens[1]
        body = tokens[2:]
        if not body or body[-1] != ";":
            raise ForthError(f"missing ';' to close definition of '{name}'")
        self.words[name] = tuple(self._compile_body(body[:-1]))

    # -- execution ---------------------------------------------------------

    def _execute_code(self, code: List[Instruction]) -> None:
        frames: list[list] = [[code, 0]]
        while frames:
            frame = frames[-1]
            body, ip = frame
            if ip >= len(body):
                frames.pop()
                continue
            frame[1] += 1
            op, arg = body[ip]
            if op == "push":
                self.stack.append(arg)
            elif op == "call":
                target = self.words[arg]
                if target and target[0][0] == "builtin":
                    # builtins are Python closures; run them directly
                    target[0][1]()
                else:
                    frames.append([list(target), 0])
            elif op == "jz":
                if self._pop("if") == 0:
                    frame[1] = arg
            elif op == "jmp":
                frame[1] = arg
            else:  # pragma: no cover
                raise ForthError(f"bad instruction: {op}")

    def evaluate(self, tokens: List[str]) -> None:
        """Evaluate a token stream (top level)."""
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok == ":":
                # gather tokens up to the closing ';'
                start = i
                try:
                    end = tokens.index(";", i)
                except ValueError:
                    raise ForthError("missing ';' to close definition")
                self.define(tokens[start:end + 1])
                i = end + 1
                continue
            code = self._compile_token(tok)
            self._execute_code(code)
            i += 1

    def clear_stack(self) -> None:
        self.stack.clear()


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def run(source: str) -> str:
    """Evaluate `source` in a fresh interpreter and capture all output."""
    import io
    import contextlib

    buf = io.StringIO()
    interp = Forth()
    with contextlib.redirect_stdout(buf):
        interp.evaluate(_tokenize(source))
    return buf.getvalue()


def _tokenize(source: str) -> List[str]:
    return source.split()


def _repl() -> None:  # pragma: no cover
    interp = Forth()
    print("forth.py -- type your Forth, Ctrl-D to exit")
    buffer = ""
    while True:
        try:
            prompt = "... " if buffer else "forth> "
            line = input(prompt)
        except EOFError:
            print()
            break
        except KeyboardInterrupt:
            print()
            buffer = ""
            continue
        buffer = (buffer + " " + line).strip()
        # keep reading while a definition is still open
        if buffer.count(":") > buffer.count(";"):
            continue
        if not buffer:
            continue
        try:
            interp.evaluate(_tokenize(buffer))
            print("ok")
        except ForthError as exc:
            print(f"error: {exc}")
        buffer = ""


if __name__ == "__main__":  # pragma: no cover
    args = sys.argv[1:]
    if args:
        sys.stdout.write(run(" ".join(args)))
    else:
        _repl()
"})
